/**
 * Layer 4. A reading span is character offsets into the passage; a
 * listening span is milliseconds into the clip. One of the two must be
 * present — evidence that does not locate itself is not evidence.
 */
export interface AdminEvidence {
  id?: string;
  /** @nullable */
  passageId?: string | null;
  /**
     * @minimum 0
     * @nullable
     */
  charStart?: number | null;
  /**
     * @minimum 0
     * @nullable
     */
  charEnd?: number | null;
  /**
     * @minimum 0
     * @nullable
     */
  audioStartMs?: number | null;
  /**
     * @minimum 0
     * @nullable
     */
  audioEndMs?: number | null;
  /**
     * The text the offsets pointed at when they were saved, so an edit to
     * the passage can be detected as having moved the span rather than
     * silently re-aiming it (TCCN-301-4).
     */
  quoteKo: string;
  quoteVi: string;
}
